CREATE TABLE accounts (
  account_id  NUMBER PRIMARY KEY,
  owner_name  VARCHAR2(50) NOT NULL,
  balance     NUMBER(12,2) NOT NULL
);

INSERT INTO accounts VALUES (1, 'Asha',  5000);
INSERT INTO accounts VALUES (2, 'Ravi',  3000);
INSERT INTO accounts VALUES (3, 'Meena', 8000);
COMMIT;

-- Session 1
UPDATE accounts SET balance = balance - 500 WHERE account_id = 1;

-- Session 2
UPDATE accounts SET balance = balance - 200 WHERE account_id = 2;

-- Session 1 (hangs, waiting for session 2)
UPDATE accounts SET balance = balance + 500 WHERE account_id = 2;

-- Session 2 (hangs, waiting for session 1)
UPDATE accounts SET balance = balance + 200 WHERE account_id = 1;

-- Session 1
ROLLBACK;

-- Session 2 continues immediately
-- 1 row updated.
COMMIT;

CREATE OR REPLACE PROCEDURE transfer (
  p_from   IN accounts.account_id%TYPE,
  p_to     IN accounts.account_id%TYPE,
  p_amount IN NUMBER
) AS
  v_balance accounts.balance%TYPE;
BEGIN
  -- Lock both rows in a fixed order: lowest id first
  SELECT balance INTO v_balance
    FROM accounts
   WHERE account_id = LEAST(p_from, p_to)
     FOR UPDATE;

  SELECT balance INTO v_balance
    FROM accounts
   WHERE account_id = GREATEST(p_from, p_to)
     FOR UPDATE;

  UPDATE accounts SET balance = balance - p_amount
   WHERE account_id = p_from;

  UPDATE accounts SET balance = balance + p_amount
   WHERE account_id = p_to;
END transfer;
/

DECLARE
  e_deadlock EXCEPTION;
  PRAGMA EXCEPTION_INIT(e_deadlock, -60);
BEGIN
  FOR attempt IN 1 .. 3 LOOP
    BEGIN
      transfer(1, 2, 500);
      COMMIT;
      EXIT;                       -- success, leave the loop
    EXCEPTION
      WHEN e_deadlock THEN
        ROLLBACK;                 -- undo the whole transfer
        IF attempt = 3 THEN
          RAISE;                  -- give up, report the error
        END IF;
        DBMS_SESSION.SLEEP(1);    -- 18c and later
    END;
  END LOOP;
END;
/

CREATE OR REPLACE PROCEDURE log_balance_change (p_id NUMBER) AS
  PRAGMA AUTONOMOUS_TRANSACTION;
BEGIN
  UPDATE accounts SET balance = balance WHERE account_id = p_id;
  COMMIT;
END;
/

UPDATE accounts SET balance = balance + 100 WHERE account_id = 3;
EXEC log_balance_change(3);   -- raises ORA-00060

